import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });
const heartbeat = () => db.prepare('INSERT INTO worker_health (id, heartbeat) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET heartbeat = excluded.heartbeat').run(Date.now());
heartbeat();
const timer = setInterval(heartbeat, 500);
// Interrupted work is recovered before queued work. Its unfinished attempt is restarted.
const recover = db.prepare(\"SELECT * FROM jobs WHERE status = 'running' ORDER BY created_at, rowid\").all() as unknown as JobRow[];
console.log('worker started');
try {
  while ("'!stopping) {
    let job = recover.shift();
    if (job) {
      db.prepare('"'UPDATE jobs SET completed = 0, updated_at = ? WHERE id = ?').run(new Date().toISOString(), job.id);
    } else {
      job = db.prepare("'`UPDATE jobs SET status = '"'running', attempts = attempts + 1, completed = 0, updated_at = ?
        WHERE id = (SELECT id FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY created_at, rowid LIMIT 1)
        RETURNING *"'`).get(new Date().toISOString(), Date.now()) as unknown as JobRow | undefined;
    }
    if (!job) { await sleep(100); continue; }
    for (let step = 1; step <= job.steps; step++) {
      await sleep(100);
      if (stopping) break;
      const now = new Date().toISOString();
      if (job.attempts <= job.fail_attempts) {
        db.prepare('"'UPDATE jobs SET status = ?, error = ?, output = NULL, available_at = ?, updated_at = ? WHERE id = ?')
          .run(job.attempts >= 3 ? 'failed' : 'queued', job.attempts >= 3 ? 'transient failure' : null, Date.now() + 500, now, job.id);
        break;
      }
      db.prepare('UPDATE jobs SET completed = ?, status = ?, output = ?, updated_at = ? WHERE id = ?')
        .run(step, step === job.steps ? 'completed' : 'running', step === job.steps ? job.input.toUpperCase() : null, now, job.id);
    }
  }
} finally {
  clearInterval(timer);
  db.prepare('DELETE FROM worker_health WHERE id = 1').run();
  db.close();
}
